// Entrada: linhas de config (chave, valor, tipo) do node Carregar Config.
// Saida: 1 item com todas as chaves ja convertidas para o tipo certo.

const cfg = {};

for (const item of $input.all()) {
  const r = item.json;
  let v = r.valor;

  if (r.tipo === 'int') v = parseInt(v, 10);
  else if (r.tipo === 'decimal') v = parseFloat(v);
  else if (r.tipo === 'bool') v = v === '1' || v === 'true' || v === 1;

  cfg[r.chave] = v;
}

const obrigatorias = [
  'MODO_BUSCA',
  'KEYWORDS_POR_EXECUCAO',
  'LIMIT_BUSCA',
  'PRECO_MINIMO',
  'PRECO_MAXIMO',
  'DESCONTO_MINIMO',
  'EXIGIR_DESCONTO',
  'SCORE_MINIMO',
];

const faltando = obrigatorias.filter((k) => cfg[k] === undefined || cfg[k] === null);
if (faltando.length) {
  throw new Error('Config faltando na tabela config: ' + faltando.join(', '));
}

if (cfg.MODO_BUSCA !== 'search' && cfg.MODO_BUSCA !== 'monitor') {
  throw new Error("MODO_BUSCA deve ser 'search' ou 'monitor'. Veio: " + cfg.MODO_BUSCA);
}

return [{ json: cfg }];

// Avanca a rotacao antes da busca: se a API falhar, a mesma keyword nao
// volta na proxima hora. Escape manual - ids sao inteiros, mas filtro
// mesmo assim para nao confiar no formato vindo do banco.

const ids = $input
  .all()
  .map((i) => parseInt(i.json.id, 10))
  .filter((n) => Number.isInteger(n) && n > 0);

if (!ids.length) {
  return [{ json: { sql: null, total: 0 } }];
}

const sql =
  'UPDATE keywords SET ultima_busca = NOW() WHERE id IN (' + ids.join(',') + ')';

return [{ json: { sql, total: ids.length } }];

// /items?ids= aceita no maximo 20 ids por chamada.
// Produz 1 item por lote, com os ids ja em string pronta pra query.

const MAX = 20;
const VALIDO = /^MLB\d+$/;

const linhas = $input.all().map((i) => i.json).filter((r) => r && r.produto_id);

const validas = linhas.filter((r) => VALIDO.test(String(r.produto_id).trim()));
const descartadas = linhas.length - validas.length;

if (descartadas > 0) {
  console.log('Watchlist: ' + descartadas + ' produto_id fora do padrao MLB999 ignorado(s)');
}

if (!validas.length) {
  return [];
}

const lotes = [];
for (let i = 0; i < validas.length; i += MAX) {
  const fatia = validas.slice(i, i + MAX);
  lotes.push({
    json: {
      ids: fatia.map((r) => String(r.produto_id).trim()).join(','),
      total: fatia.length,
      // guarda a categoria de cada id para o Normalizar reusar
      categorias: fatia.reduce((acc, r) => {
        acc[String(r.produto_id).trim()] = r.categoria_id ?? null;
        return acc;
      }, {}),
    },
  });
}

return lotes;

// Aceita os DOIS formatos de entrada:
//   search  -> { results: [ item, ... ] }
//   monitor -> [ { code: 200, body: item }, ... ]
// Nunca chuta valor: campo ausente vira null e o score simplesmente nao pontua.

const modo = $('Montar Config').first().json.MODO_BUSCA;

// --- categoria por keyword (modo search) --------------------------------
// O node HTTP roda 1x por keyword, na ordem, entao o indice alinha.
let keywords = [];
try {
  keywords = $('Selecionar Keywords').all().map((i) => i.json);
} catch (e) {
  keywords = [];
}

// --- categoria por produto_id (modo monitor) ----------------------------
let mapaCategorias = {};
if (modo === 'monitor') {
  try {
    for (const lote of $('Montar Lotes de 20').all()) {
      Object.assign(mapaCategorias, lote.json.categorias || {});
    }
  } catch (e) {
    mapaCategorias = {};
  }
}

function imagemDe(item) {
  // /items/{id} traz pictures[].secure_url; /search traz apenas thumbnail.
  if (Array.isArray(item.pictures) && item.pictures.length) {
    const u = item.pictures[0].secure_url || item.pictures[0].url || null;
    if (u) return String(u).replace('http://', 'https://');
  }
  if (item.thumbnail) {
    return String(item.thumbnail)
      .replace('http://', 'https://')
      .replace(/-I\.jpg$/, '-O.jpg');
  }
  return null;
}

function avaliacaoDe(item) {
  // Campo historicamente removido/ofuscado pelo ML. Le defensivamente.
  const r = item.reviews;
  if (r && typeof r.rating_average === 'number' && r.rating_average > 0) {
    return Number(r.rating_average);
  }
  return null;
}

function vendidosDe(item) {
  const v = item.sold_quantity;
  return typeof v === 'number' && v >= 0 ? v : null;
}

function catalogoDe(item) {
  if (item.catalog_listing === true) return 1;
  if (item.catalog_product_id) return 1;
  return 0;
}

function normalizar(item, categoriaId) {
  const preco = Number(item.price);
  if (!preco || !Number.isFinite(preco)) return null;

  const orig = Number(item.original_price);
  const precoOriginal = orig && Number.isFinite(orig) && orig > preco ? orig : null;

  const desconto = precoOriginal
    ? Math.round((1 - preco / precoOriginal) * 100)
    : null;

  return {
    produto_id: item.id,
    titulo: item.title || null,
    categoria_id: categoriaId ?? null,
    preco_atual: preco,
    preco_original: precoOriginal,
    desconto,
    frete_gratis: item.shipping && item.shipping.free_shipping ? 1 : 0,
    condicao: item.condition || null,
    catalogo: catalogoDe(item),
    vendidos: vendidosDe(item),
    avaliacao: avaliacaoDe(item),
    link_produto: item.permalink || null,
    imagem: imagemDe(item),
    origem: modo,
  };
}

const saida = [];
const entradas = $input.all();
let erros = 0;

for (let idx = 0; idx < entradas.length; idx++) {
  const j = entradas[idx].json;

  if (!j || j.error) {
    erros++;
    continue;
  }

  // formato search
  if (Array.isArray(j.results)) {
    const cat = keywords[idx] ? keywords[idx].categoria_id : null;
    for (const item of j.results) {
      const n = normalizar(item, cat);
      if (n) saida.push(n);
    }
    continue;
  }

  // formato monitor: array inteiro num item
  if (Array.isArray(j)) {
    for (const r of j) {
      if (r && r.code === 200 && r.body) {
        const n = normalizar(r.body, mapaCategorias[r.body.id] ?? null);
        if (n) saida.push(n);
      }
    }
    continue;
  }

  // formato monitor: n8n quebrou o array em 1 item por entrada
  if (j.code === 200 && j.body) {
    const n = normalizar(j.body, mapaCategorias[j.body.id] ?? null);
    if (n) saida.push(n);
    continue;
  }

  // item cru (caso o ML devolva o objeto direto)
  if (j.id && j.title) {
    const n = normalizar(j, mapaCategorias[j.id] ?? null);
    if (n) saida.push(n);
  }
}

if (!saida.length) {
  const motivo =
    erros > 0
      ? 'Todas as ' + erros + ' chamadas a API falharam (403 no /search? confira 2.1).'
      : 'A API respondeu, mas nenhum item veio no formato esperado.';
  console.log('Normalizar: 0 itens. ' + motivo);
}

return saida.map((json) => ({ json }));

// Filtra pelos limites da config e pontua de 0 a 100.
// score_detalhe guarda a conta de cada critério: null = criterio sem dado,
// 0 = tinha dado e nao pontuou. E o que a FASE 7 confere.

const cfg = $('Montar Config').first().json;

const precoMin = Number(cfg.PRECO_MINIMO);
const precoMax = Number(cfg.PRECO_MAXIMO);
const descontoMin = Number(cfg.DESCONTO_MINIMO);
const exigirDesconto = cfg.EXIGIR_DESCONTO === true || cfg.EXIGIR_DESCONTO === 1;
const scoreMin = Number(cfg.SCORE_MINIMO);

function pontuar(o) {
  let s = 0;
  const d = {};

  const desc = o.desconto;
  if (desc == null) d.desconto = null;
  else if (desc >= 41) { s += 40; d.desconto = 40; }
  else if (desc >= 31) { s += 30; d.desconto = 30; }
  else if (desc >= 21) { s += 20; d.desconto = 20; }
  else if (desc >= 15) { s += 10; d.desconto = 10; }
  else d.desconto = 0;

  if (o.frete_gratis) { s += 10; d.frete_gratis = 10; } else d.frete_gratis = 0;

  if (o.avaliacao == null) d.avaliacao = null;
  else if (o.avaliacao >= 4.5) { s += 15; d.avaliacao = 15; }
  else if (o.avaliacao >= 4.0) { s += 8; d.avaliacao = 8; }
  else d.avaliacao = 0;

  if (o.vendidos == null) d.vendas = null;
  else if (o.vendidos >= 500) { s += 15; d.vendas = 15; }
  else if (o.vendidos >= 100) { s += 10; d.vendas = 10; }
  else if (o.vendidos >= 25) { s += 5; d.vendas = 5; }
  else d.vendas = 0;

  if (o.preco_atual >= 50 && o.preco_atual <= 1500) { s += 10; d.faixa_preco = 10; }
  else d.faixa_preco = 0;

  if (o.catalogo) { s += 10; d.catalogo = 10; } else d.catalogo = 0;

  if (o.condicao === 'new') { s += 5; d.novo = 5; } else d.novo = 0;

  const total = Math.min(100, s);
  d.total = total;
  return { score: total, detalhe: d };
}

const aprovados = [];
const vistos = new Set();
const contagem = {
  entrada: 0,
  sem_link: 0,
  sem_imagem: 0,
  fora_de_preco: 0,
  sem_desconto: 0,
  desconto_baixo: 0,
  score_baixo: 0,
  duplicado_na_rodada: 0,
  aprovado: 0,
};

for (const item of $input.all()) {
  const o = item.json;
  contagem.entrada++;

  if (!o.produto_id || !o.titulo) { contagem.sem_link++; continue; }
  if (!o.link_produto) { contagem.sem_link++; continue; }
  if (!o.imagem) { contagem.sem_imagem++; continue; }

  if (o.preco_atual < precoMin || o.preco_atual > precoMax) {
    contagem.fora_de_preco++;
    continue;
  }

  if (o.desconto == null) {
    if (exigirDesconto) { contagem.sem_desconto++; continue; }
  } else if (o.desconto < descontoMin) {
    contagem.desconto_baixo++;
    continue;
  }

  const { score, detalhe } = pontuar(o);
  if (score < scoreMin) { contagem.score_baixo++; continue; }

  // mesma rodada pode trazer o mesmo produto por 2 keywords diferentes
  const chave = o.produto_id + '|' + o.preco_atual.toFixed(2);
  if (vistos.has(chave)) { contagem.duplicado_na_rodada++; continue; }
  vistos.add(chave);

  contagem.aprovado++;
  aprovados.push({ ...o, score, score_detalhe: detalhe });
}

console.log('Filtrar e Pontuar: ' + JSON.stringify(contagem));

aprovados.sort((a, b) => b.score - a.score);

return aprovados.map((json) => ({ json }));

// Escape manual, de proposito: titulo do ML tem virgula e apostrofo, e a
// opcao Query Parameters do node MySQL e uma lista separada por virgula.
// INSERT IGNORE + UNIQUE (produto_id, preco_atual) resolve a duplicata.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return 'NULL';
    return String(v);
  }
  if (typeof v === 'boolean') return v ? '1' : '0';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\u0000/g, '')
    .replace(/[\r\n]+/g, ' ')
    .trim();
  return "'" + s + "'";
}

const linhas = [];

for (const item of $input.all()) {
  const o = item.json;

  linhas.push(
    '(' +
      [
        esc(o.produto_id),
        esc(String(o.titulo).slice(0, 250)),
        esc(o.categoria_id),
        esc(Number(o.preco_atual).toFixed(2)),
        o.preco_original == null ? 'NULL' : esc(Number(o.preco_original).toFixed(2)),
        esc(o.desconto),
        esc(o.frete_gratis ? 1 : 0),
        esc(o.condicao),
        esc(o.catalogo ? 1 : 0),
        esc(o.vendidos),
        esc(o.avaliacao),
        esc(String(o.link_produto).slice(0, 490)),
        esc(String(o.imagem).slice(0, 490)),
        esc(o.score),
        esc(JSON.stringify(o.score_detalhe || {})),
      ].join(', ') +
      ')'
  );
}

if (!linhas.length) {
  return [{ json: { sql: null, total: 0 } }];
}

const sql =
  'INSERT IGNORE INTO ofertas\n' +
  '  (produto_id, titulo, categoria_id, preco_atual, preco_original, desconto,\n' +
  '   frete_gratis, condicao, catalogo, vendidos, avaliacao, link_produto,\n' +
  '   imagem, score, score_detalhe)\n' +
  'VALUES\n  ' +
  linhas.join(',\n  ');

return [{ json: { sql, total: linhas.length } }];

// Ramo paralelo: mantem a watchlist com o menor preco ja visto.
// Roda nos dois modos - no modo search isso vai construindo a watchlist
// que o modo monitor usa depois, caso o /search comece a dar 403.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/[\r\n]+/g, ' ')
    .trim();
  return "'" + s + "'";
}

const vistos = new Map();

for (const item of $input.all()) {
  const o = item.json;
  if (!o.produto_id) continue;
  // mantem a ocorrencia de menor preco dentro da rodada
  const atual = vistos.get(o.produto_id);
  if (!atual || o.preco_atual < atual.preco_atual) vistos.set(o.produto_id, o);
}

const linhas = [...vistos.values()].map(
  (o) =>
    '(' +
    [
      esc(o.produto_id),
      esc(o.categoria_id),
      esc(Number(o.preco_atual).toFixed(2)),
      esc(String(o.titulo || '').slice(0, 250)),
    ].join(', ') +
    ', NOW())'
);

if (!linhas.length) {
  return [{ json: { sql: null, total: 0 } }];
}

// LEAST guarda o menor preco historico sem apagar o que ja havia
const sql =
  'INSERT INTO watchlist\n' +
  '  (produto_id, categoria_id, preco_referencia, titulo, ultima_checagem)\n' +
  'VALUES\n  ' +
  linhas.join(',\n  ') +
  '\nON DUPLICATE KEY UPDATE\n' +
  '  preco_referencia = LEAST(COALESCE(watchlist.preco_referencia, VALUES(preco_referencia)), VALUES(preco_referencia)),\n' +
  '  titulo = COALESCE(VALUES(titulo), watchlist.titulo),\n' +
  '  categoria_id = COALESCE(VALUES(categoria_id), watchlist.categoria_id),\n' +
  '  ultima_checagem = NOW()';

return [{ json: { sql, total: linhas.length } }];
